1	import 'package:flutter/material.dart';
2	import 'package:flutter/services.dart';
3	import 'package:flutter_test/flutter_test.dart';
4	import 'package:fpdart/fpdart.dart';
5	import 'package:mocktail/mocktail.dart';
6	
7	import 'package:cerne/core/di/injection_container.dart';
8	import 'package:cerne/core/failure/failure.dart';
9	import 'package:cerne/features/auth/domain/entities/authenticated_user.dart';
10	import 'package:cerne/features/auth/domain/entities/session_status.dart';
11	import 'package:cerne/features/auth/domain/repositories/auth_repository.dart';
12	import 'package:cerne/features/auth/domain/repositories/session_repository.dart';
13	import 'package:cerne/main.dart';
14	
15	class MockAuthRepository extends Mock implements AuthRepository {}
16	
17	class MockSessionRepository extends Mock implements SessionRepository {}
18	
19	/// Proves the one real production composition root — `CerneApp` resolving
20	/// `sl<AuthCubit>()` and wiring `onAuthenticated` to
21	/// `Navigator.pushReplacement` — actually works end to end (code review of
22	/// story-1-3-account-creation-and-login), and (Story 1.4) that `home`
23	/// actually branches on `SessionRepository.statusStream`'s first emission
24	/// instead of hardcoding `AuthScreen`. Every other test either stops at DI
25	/// registration (`bootstrap_integration_test.dart`) or supplies its own
26	/// `AuthCubit`/`onAuthenticated` (`auth_screen_test.dart`), so neither
27	/// exercises `main.dart`'s own wiring.
28	void main() {
29	  TestWidgetsFlutterBinding.ensureInitialized();
30	
31	  const secureStorageChannel = MethodChannel(
32	    'plugins.it_nomads.com/flutter_secure_storage',
33	  );
34	  final fakeNativeStorage = <String, String>{};
35	
36	  Future<dynamic> handleSecureStorageCall(MethodCall call) async {
37	    final args = call.arguments as Map<dynamic, dynamic>;
38	    switch (call.method) {
39	      case 'write':
40	        fakeNativeStorage[args['key'] as String] = args['value'] as String;
41	        return null;
42	      case 'read':
43	        return fakeNativeStorage[args['key'] as String];
44	      case 'delete':
45	        fakeNativeStorage.remove(args['key'] as String);
46	        return null;
47	      case 'containsKey':
48	        return fakeNativeStorage.containsKey(args['key'] as String);
49	      default:
50	        return null;
51	    }
52	  }
53	
54	  setUp(() async {
55	    TestDefaultBinaryMessengerBinding.instance.defaultBinaryMessenger
56	        .setMockMethodCallHandler(
57	          secureStorageChannel,
58	          handleSecureStorageCall,
59	        );
60	    await resetCoreDependencies();
61	    await setupCoreDependencies();
62	  });
63	
64	  tearDown(() async {
65	    TestDefaultBinaryMessengerBinding.instance.defaultBinaryMessenger
66	        .setMockMethodCallHandler(secureStorageChannel, null);
67	    fakeNativeStorage.clear();
68	    await resetCoreDependencies();
69	  });
70	
71	  testWidgets(
72	    'CerneApp resolves the real AuthCubit and navigates to the post-auth '
73	    'placeholder once onAuthenticated fires',
74	    (tester) async {
75	      final mockAuthRepository = MockAuthRepository();
76	      when(
77	        () => mockAuthRepository.logIn(
78	          email: any(named: 'email'),
79	          password: any(named: 'password'),
80	        ),
81	      ).thenAnswer(
82	        (_) async => right(const AuthenticatedUser(id: 'u1', email: 'a@b.com')),
83	      );
84	
85	      // Swaps only the repository, before AuthCubit's first resolution, so
86	      // CerneApp's own `sl<AuthCubit>()` lookup and `main.dart`'s real
87	      // `onAuthenticated` callback run unchanged.
88	      sl.unregister<AuthRepository>();
89	      sl.registerLazySingleton<AuthRepository>(() => mockAuthRepository);
90	
91	      await tester.pumpWidget(const CerneApp());
92	      // Lets the real `SessionRepository.restoreSession()` boot call (no
93	      // stored refresh token in the fake secure-storage channel, so it
94	      // resolves to `unauthenticated` with no network call) settle before
95	      // interacting with `AuthScreen`.
96	      await tester.pumpAndSettle();
97	
98	      await tester.enterText(
99	        find.widgetWithText(TextField, 'E-mail'),
100	        'a@b.com',
101	      );
102	      await tester.enterText(
103	        find.widgetWithText(TextField, 'Senha'),
104	        'segredo123',
105	      );
106	      await tester.tap(find.text('Entrar'));
107	      await tester.pumpAndSettle();
108	
109	      expect(find.text('Autenticado'), findsOneWidget);
110	      expect(find.text('Bem-vindo de volta'), findsNothing);
111	    },
112	  );
113	
114	  testWidgets(
115	    'CerneApp lands on the post-auth placeholder when statusStream emits '
116	    'authenticated, with no AuthScreen ever shown',
117	    (tester) async {
118	      final mockSessionRepository = MockSessionRepository();
119	      when(() => mockSessionRepository.restoreSession())
120	          .thenAnswer((_) async => right(unit));
121	      when(() => mockSessionRepository.statusStream)
122	          .thenAnswer((_) => Stream.value(SessionStatus.authenticated));
123	
124	      sl.unregister<SessionRepository>();
125	      sl.registerLazySingleton<SessionRepository>(() => mockSessionRepository);
126	
127	      await tester.pumpWidget(const CerneApp());
128	      await tester.pumpAndSettle();
129	
130	      expect(find.text('Autenticado'), findsOneWidget);
131	      expect(find.text('Entrar'), findsNothing);
132	    },
133	  );
134	
135	  testWidgets(
136	    'CerneApp lands on AuthScreen when statusStream emits unauthenticated',
137	    (tester) async {
138	      final mockSessionRepository = MockSessionRepository();
139	      when(
140	        () => mockSessionRepository.restoreSession(),
141	      ).thenAnswer((_) async => left(const AuthExpired(message: 'No session')));
142	      when(() => mockSessionRepository.statusStream)
143	          .thenAnswer((_) => Stream.value(SessionStatus.unauthenticated));
